- (BOOL)isFlipped{return YES;}
- (NSRect)imageRect{if(pixelWidth<1||pixelHeight<1)return NSZeroRect;double scale=std::min(self.bounds.size.width/pixelWidth,self.bounds.size.height/pixelHeight);return NSMakeRect((self.bounds.size.width-pixelWidth*scale)/2,(self.bounds.size.height-pixelHeight*scale)/2,pixelWidth*scale,pixelHeight*scale);}
